import { useState, KeyboardEvent } from 'react';
import { JxInputField, JxChip } from '@jinx-ui/react';

interface ArticleTagPickerProps {
  label?: string;
  placeholder?: string;
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagPicker({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  onChange,
}: ArticleTagPickerProps) {
  const [tags, setTags] = useState<string[]>([]);
  const [draft, setDraft] = useState('');

  const commit = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  const addTag = () => {
    const value = draft.trim();
    if (!value || tags.includes(value)) {
      setDraft('');
      return;
    }
    commit([...tags, value]);
    setDraft('');
  };

  const removeTag = (index: number) => {
    commit(tags.filter((_, i) => i !== index));
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      addTag();
    } else if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      removeTag(tags.length - 1);
    }
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-sm, 8px)',
      }}
    >
      <JxInputField
        label={label}
        placeholder={placeholder}
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={handleKeyDown}
        helperText="Enter — добавить тег, Backspace на пустом поле — удалить последний"
      />
      <div
        role="list"
        aria-label="Выбранные теги"
        style={{
          display: 'flex',
          flexWrap: 'wrap',
          gap: 'var(--jx-space-xs, 6px)',
        }}
      >
        {tags.map((tag, index) => (
          <span role="listitem" key={tag}>
            <JxChip removable onRemove={() => removeTag(index)}>
              {tag}
            </JxChip>
          </span>
        ))}
      </div>
    </div>
  );
}

